pub struct Article<State> { pub attributes: Vec<(String, String)>, pub styles: crate::Style, pub events: Vec<(String, VdomEventHandler<State>)>, pub children: Vec<VdomNode<State>> }
impl<State> Default for Article<State> { fn default() -> Self { Self::new() } }
impl<State> Article<State> { pub fn new() -> Self { Self { attributes: Vec::new(), styles: crate::Style::new(), events: Vec::new(), children: Vec::new() } } pub fn attribute(mut self, key: impl Into<String>, value: impl Into<String>) -> Self { self.attributes.push((key.into(), value.into())); self } pub fn id(self, value: impl Into<String>) -> Self { self.attribute("id", value) } pub fn class(self, value: impl Into<String>) -> Self { self.attribute("class", value) } pub fn type_(self, value: impl Into<String>) -> Self { self.attribute("type", value) } pub fn style(mut self, style: impl Into<crate::Style>) -> Self { self.styles = style.into(); self } pub fn popover(self) -> Self { self.attribute("popover", "auto") } pub fn children(mut self, children: impl Into<Vec<VdomNode<State>>>) -> Self { self.children = children.into(); self } pub fn into_node(self) -> VdomNode<State> { VdomNode::Element(VdomElement { element_name: "article".to_string(), attributes: self.attributes, styles: self.styles, events: self.events, children: self.children }) } }
