pub struct Bdi<State> { pub attributes: Vec<(String, String)>, pub styles: crate::Style, pub events: Vec<(String, VdomEventHandler<State>)>, pub children: Vec<VdomNode<State>> }
impl<State> Default for Bdi<State> { fn default() -> Self { Self::new() } }
